{"functions": [{"name": "EtherLotto", "modifiers": [], "visibility": "", "is_view": false, "external_calls": [["msg", "send"]], "state_writes": ["bank"], "internal_calls": [], "reads_timestamp": false, "body": "
        bank = msg.sender;
    "}, {"name": "play", "modifiers": [], "visibility": "", "is_view": false, "external_calls": [["bank", "transfer"], ["msg", "send"], ["er", "transfer"]], "state_writes": ["random", "pot"], "internal_calls": [], "reads_timestamp": true, "body": "

        // Participants must spend some fixed ether before playing lottery.
        assert(msg.value == TICKET_AMOUNT);

        // Increase pot for each participant.
        pot += msg.value;

        // Compute some *almost random* value for selecting winner from current transaction.
        // <yes> <report> TIME_MANIPULATION
        var random = uint(sha3(block.timestamp)) % 2;

        // Distribution: 50% of participants will be winners.
        if (random == 0) {

            // Send fee to bank account.
            bank.transfer(FEE_AMOUNT);

            // Send jackpot to winner.
            msg.sender.transfer(pot - FEE_AMOUNT);

            // Restart jackpot.
            pot = 0;
        }
    "}], "declared_modifiers": [], "pragma": "0.4.15", "state_vars": ["bank", "pot"]}

