{"functions": [{"name": "setBotAddress", "modifiers": ["onlyOwner"], "visibility": "external", "is_view": false, "external_calls": [], "state_writes": ["autoPlayBot"], "internal_calls": [], "reads_timestamp": false, "body": "
        autoPlayBot = autoPlayBotAddress;
    "}, {"name": "setSecretSigner", "modifiers": ["onlyOwner"], "visibility": "external", "is_view": false, "external_calls": [], "state_writes": ["secretSigner"], "internal_calls": [], "reads_timestamp": false, "body": "
        secretSigner = _secretSigner;
    "}, {"name": "wager", "modifiers": [], "visibility": "external", "is_view": false, "external_calls": [["msg", "send"], ["whale", "call"]], "state_writes": ["bet", "amount", "player", "signatureHash", "donate_amount", "amount", "blockNumber", "betMask", "player"], "internal_calls": [], "reads_timestamp": true, "body": " 
        Bet storage bet = bets[ticketID];
        uint amount = msg.value;
        address player = msg.sender;
        require (bet.player == address(0), "Ticket is not new one!");
        require (amount >= MIN_BET, "Your bet is lower than minimum bet amount");
        require (amount <= MAX_BET, "Your bet is higher than maximum bet amount");
        require (getCollateralBalance() >= 2 * amount, "If we accept this, this contract will be in danger!");

        require (block.number <= ticketLastBlock, "Ticket has expired.");
        bytes32 signatureHash = keccak256(abi.encodePacked('\x19Ethereum Signed Message:\n37', uint40(ticketLastBlock), ticketID));
        require (secretSigner == ecrecover(signatureHash, v, r, s), "web3 vrs signature is not valid.");

        jackpotSize += amount * JACKPOT_FEE / 1000;
        devFeeSize += amount * DEV_FEE / 1000;
        lockedInBets += amount * WIN_X / 1000;

        uint donate_amount = amount * DONATING_X / 1000;
        // <yes> <report> UNCHECKED_LL_CALLS
        whale.call.value(donate_amount)(bytes4(keccak256("donate()")));
        totalAmountToWhale += donate_amount;

        bet.amount = amount;
        bet.blockNumber = block.number;
        bet.betMask = bMask;
        bet.player = player;

        emit Wager(ticketID, bet.amount, bet.blockNumber, bet.betMask, bet.player);
    "}, {"name": "play", "modifiers": [], "visibility": "external", "is_view": false, "external_calls": [], "state_writes": ["ticketID", "bet", "blockNumber", "random", "maskRes", "jackpotRes", "tossWinAmount", "tossWin", "jackpotWin", "tossWin", "jackpotWin", "jackpotSize", "amount"], "internal_calls": [], "reads_timestamp": true, "body": "
        uint ticketID = uint(keccak256(abi.encodePacked(ticketReveal)));
        Bet storage bet = bets[ticketID];
        require (bet.player != address(0), "TicketID is not correct!");
        require (bet.amount != 0, "Ticket is already used one!");
        uint256 blockNumber = bet.blockNumber;
        if(blockNumber < block.number && blockNumber >= block.number - BET_EXPIRATION_BLOCKS)
        {
            uint256 random = uint256(keccak256(abi.encodePacked(blockhash(blockNumber),  ticketReveal)));
            bool maskRes = (random % 2) !=0;
            uint jackpotRes = random % JACKPOT_MODULO;

            uint tossWinAmount = bet.amount * WIN_X / 1000;

            uint tossWin = 0;
            uint jackpotWin = 0;

            if(bet.betMask == maskRes) {
                tossWin = tossWinAmount;
            }
            if(jackpotRes == 0) {
                jackpotWin = jackpotSize;
                jackpotSize = 0;
            }
            if (jackpotWin > 0) {
                emit JackpotPayment(bet.player, ticketID, jackpotWin);
            }
            if(tossWin + jackpotWin > 0)
            {
                payout(bet.player, tossWin + jackpotWin, ticketID, maskRes, jackpotRes);
            }
            else 
            {
                loseWager(bet.player, bet.amount, ticketID, maskRes, jackpotRes);
            }
            lockedInBets -= tossWinAmount;
            bet.amount = 0;
        }
        else
        {
            revert();
        }
    "}, {"name": "donateForContractHealth", "modifiers": [], "visibility": "external", "is_view": false, "external_calls": [["msg", "send"], ["msg", "send"]], "state_writes": [], "internal_calls": [], "reads_timestamp": false, "body": "
        donateAmount[msg.sender] += msg.value;
        emit Donate(msg.value, msg.sender);
    "}, {"name": "withdrawDonation", "modifiers": [], "visibility": "external", "is_view": false, "external_calls": [["msg", "send"], ["msg", "send"], ["msg", "send"]], "state_writes": [], "internal_calls": [], "reads_timestamp": false, "body": "
        require(donateAmount[msg.sender] >= amount, "You are going to withdraw more than you donated!");

        if (sendFunds(msg.sender, amount)){
            donateAmount[msg.sender] -= amount;
        }
    "}, {"name": "refund", "modifiers": [], "visibility": "external", "is_view": false, "external_calls": [], "state_writes": ["bet"], "internal_calls": [], "reads_timestamp": true, "body": "
        Bet storage bet = bets[ticketID];

        require (bet.amount != 0, "this ticket has no balance");
        require (block.number > bet.blockNumber + BET_EXPIRATION_BLOCKS, "this ticket is expired.");
        sendRefund(ticketID);
    "}, {"name": "withdrawDevFee", "modifiers": ["onlyOwner"], "visibility": "external", "is_view": false, "external_calls": [], "state_writes": [], "internal_calls": [], "reads_timestamp": false, "body": "
        require (devFeeSize >= withdrawAmount, "You are trying to withdraw more amount than developer fee.");
        require (withdrawAmount <= address(this).balance, "Contract balance is lower than withdrawAmount");
        require (devFeeSize <= address(this).balance, "Not enough funds to withdraw.");
        if (sendFunds(withdrawAddress, withdrawAmount)){
            devFeeSize -= withdrawAmount;
        }
    "}, {"name": "withdrawBotFee", "modifiers": ["onlyBot"], "visibility": "external", "is_view": false, "external_calls": [], "state_writes": [], "internal_calls": [], "reads_timestamp": false, "body": "
        require (devFeeSize >= withdrawAmount, "You are trying to withdraw more amount than developer fee.");
        require (withdrawAmount <= address(this).balance, "Contract balance is lower than withdrawAmount");
        require (devFeeSize <= address(this).balance, "Not enough funds to withdraw.");
        if (sendFunds(autoPlayBot, withdrawAmount)){
            devFeeSize -= withdrawAmount;
        }
    "}, {"name": "getBetInfo", "modifiers": [], "visibility": "external", "is_view": false, "external_calls": [], "state_writes": ["bet"], "internal_calls": [], "reads_timestamp": false, "body": "
        Bet storage bet = bets[ticketID];
        return (bet.amount, bet.blockNumber, bet.betMask, bet.player);
    "}, {"name": "getContractBalance", "modifiers": [], "visibility": "external", "is_view": false, "external_calls": [], "state_writes": [], "internal_calls": [], "reads_timestamp": false, "body": "
        return address(this).balance;
    "}, {"name": "getCollateralBalance", "modifiers": [], "visibility": "public", "is_view": false, "external_calls": [], "state_writes": [], "internal_calls": [], "reads_timestamp": false, "body": "
        if (address(this).balance > lockedInBets + jackpotSize + devFeeSize)
            return address(this).balance - lockedInBets - jackpotSize - devFeeSize;
        return 0;
    "}, {"name": "kill", "modifiers": ["onlyOwner"], "visibility": "external", "is_view": false, "external_calls": [], "state_writes": [], "internal_calls": [], "reads_timestamp": false, "body": "
        require (lockedInBets == 0, "All bets should be processed (settled or refunded) before self-destruct.");
        selfdestruct(owner);
    "}, {"name": "payout", "modifiers": [], "visibility": "internal", "is_view": false, "external_calls": [["winner", "transfer"]], "state_writes": [], "internal_calls": [], "reads_timestamp": false, "body": "        
        winner.transfer(ethToTransfer);
        emit Win(winner, ethToTransfer, ticketID, maskRes, jackpotRes);
    "}, {"name": "sendRefund", "modifiers": [], "visibility": "internal", "is_view": false, "external_calls": [["requester", "transfer"]], "state_writes": ["bet", "requester", "ethToTransfer", "tossWinAmount", "amount"], "internal_calls": [], "reads_timestamp": false, "body": "
        Bet storage bet = bets[ticketID];
        address requester = bet.player;
        uint256 ethToTransfer = bet.amount;        
        requester.transfer(ethToTransfer);

        uint tossWinAmount = bet.amount * WIN_X / 1000;
        lockedInBets -= tossWinAmount;

        bet.amount = 0;
        emit Refund(ticketID, ethToTransfer, requester);
    "}, {"name": "sendFunds", "modifiers": [], "visibility": "private", "is_view": false, "external_calls": [["paidUser", "send"]], "state_writes": ["success"], "internal_calls": [], "reads_timestamp": false, "body": "
        bool success = paidUser.send(amount);
        if (success) {
            emit Payment(paidUser, amount);
        } else {
            emit FailedPayment(paidUser, amount);
        }
        return success;
    "}, {"name": "loseWager", "modifiers": [], "visibility": "internal", "is_view": false, "external_calls": [], "state_writes": [], "internal_calls": [], "reads_timestamp": false, "body": "
        emit Lose(player, amount, ticketID, maskRes, jackpotRes);
    "}, {"name": "clearStorage", "modifiers": [], "visibility": "external", "is_view": false, "external_calls": [], "state_writes": ["length", "i"], "internal_calls": [], "reads_timestamp": false, "body": "
        uint length = toCleanTicketIDs.length;

        for (uint i = 0; i < length; i++) {
            clearProcessedBet(toCleanTicketIDs[i]);
        }
    "}, {"name": "clearProcessedBet", "modifiers": [], "visibility": "private", "is_view": false, "external_calls": [], "state_writes": ["bet", "blockNumber", "betMask", "player"], "internal_calls": [], "reads_timestamp": true, "body": "
        Bet storage bet = bets[ticketID];

        // Do not overwrite active bets with zeros; additionally prevent cleanup of bets
        // for which ticketID signatures may have not expired yet (see whitepaper for details).
        if (bet.amount != 0 || block.number <= bet.blockNumber + BET_EXPIRATION_BLOCKS) {
            return;
        }

        bet.blockNumber = 0;
        bet.betMask = false;
        bet.player = address(0);
    "}, {"name": "transferAnyERC20Token", "modifiers": ["onlyOwner"], "visibility": "public", "is_view": false, "external_calls": [], "state_writes": [], "internal_calls": [], "reads_timestamp": false, "body": "
        return ERC20Interface(tokenAddress).transfer(tokenOwner, tokens);
    "}], "declared_modifiers": ["onlyOwner", "onlyBot", "checkContractHealth"], "pragma": "0.4.24", "state_vars": ["owner", "autoPlayBot", "secretSigner", "whale", "jackpotSize", "devFeeSize", "lockedInBets", "totalAmountToWhale", "amount", "blockNumber", "betMask", "player"]}

